entries[366931] = { ["name"] = "Demütigende Schläge", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Prototyp der Pflicht schlägt sein aktuelles Ziel, fügt ihm 209082 körperlichen Schaden zu und erhöht den durch 'Demütigender Schlag' erlittenen Schaden 40 Sek. lang um 100%.\n\nZusätzlich strahlt der Einschlag 30% des verursachten Schadens als körperlichen Schaden auf alle anderen Spielercharaktere ab." }
