entries[367484] = { ["name"] = "Boshaftes Klauenzerfleischen", ["text"] = "Unbegrenzte Reichweite\nWirken in 3 sek.\nDer Gnoll fixiert sich auf einen Spielercharakter und zerfleischt ihn, wodurch der Spielercharakter 5 Sek. lang alle 1 Sek. 2424449 körperlichen Schaden erleidet." }
