entries[367486] = { ["name"] = "Staubwelle", ["text"] = "Sofort\nWenn sich keine Spielercharaktere an dem Ort befinden, an dem Skolex auftaucht, verursacht die Schockwelle aus Staub 83539 kosmischen Schaden und belegt alle Spielercharaktere mit 10 Stapeln von ' Ephemerastaub '." }
